custom.expression:
let y=p.y+0.11;
let sky=mix(c3*0.77,c2*0.67,smoothstep(0.0,0.55,y));
var col=mix(sky,c4*0.83,0.48*exp(-abs(y)*8.0));
for(var i=0;i<12;i++){
 let k=f32(i);
 let r=hash(vec2<f32>(k,7.0));
 let x=p.x-(k-5.5)*0.153;
 let h=(0.14+0.36*r)*mix(0.44,1.0,smoothstep(0.02,0.32,abs(p.x)));
 let top=select(h,0.49,i==8);
 let a=abs(x);
 let w=0.046+r*0.029;
 let wall=max(a-w,max(-0.10-y,y-top));
 let crown=max(a-max(0.002,0.037-(y-top)*0.68),max(top-y,y-top-0.087));
 let d=min(wall,select(1.0,crown,i==8));
 let g=vec2<f32>(x*134.0,y*93.0);
 let s=abs(fract(g)-0.5);
 let lit=step(0.46,hash(floor(g)+vec2<f32>(k*17.0,0.0)));
 let win=(1.0-smoothstep(0.24,0.43,max(s.x,s.y)))*lit*window_lights;
 let face=mix(c1,c2,(0.28-0.22*smoothstep(-0.008,0.008,x))+0.12*r);
 let tower=mix(face,mix(c2,c4,r),win*0.82);
 col=mix(col,mix(tower,c4,0.78*(1.0-smoothstep(0.0,0.004,crown))*select(0.0,1.0,i==8)),1.0-smoothstep(0.0,0.002,d));
}
let z=max(-y,0.002);
let u=p.x/z;
let v=0.22/z+t*cruise_speed;
let tick=fract(v);
let dash=smoothstep(0.08,0.16,tick)*(1.0-smoothstep(0.43,0.51,tick))*smoothstep(0.027,0.095,z);
let lane=fill(abs(abs(p.x)-0.47*z)-0.008*z-0.0008)*dash;
let edge=fill(abs(abs(p.x)-1.40*z)-0.012*z-0.0008);
let asphalt=mix(c2*0.49,c1*1.36,smoothstep(0.0,0.48,z));
let deck=mix(asphalt,c4*0.84,max(lane*0.85,edge*0.67));
let rail=fill(abs(abs(p.x)-1.59*z)-0.105*z-0.001);
col=mix(col,mix(c1*1.25,c2*0.76,tick*0.55+rail*0.33),rail*fill(y));
col=mix(col,deck,fill(abs(u)-1.49)*fill(y));
let q=p-vec2<f32>(-0.093,-0.048);
let board=sd_box(q,vec2<f32>(0.046,0.022));
let pole=sd_box(q+vec2<f32>(0.050,0.065),vec2<f32>(0.002,0.062));
col=mix(col,c2*0.52,fill(pole));
col=mix(col,c5*0.57,fill(board));
let shield=sd_box(q+vec2<f32>(0.026,0.0),vec2<f32>(0.010,0.012));
let bars=sd_box(vec2<f32>(q.x-0.009,abs(q.y)-0.006),vec2<f32>(0.019,0.001));
col=mix(col,mix(c2,c3,fill(0.004-q.y)),fill(shield));
col=mix(col,c5,fill(bars));
for(var j=0;j<6;j++){
 let n=f32(j);
 let f=fract(t*cruise_speed*(0.19+0.014*n)+n*0.371);
 let dep=0.037+0.46*f*f;
 let x=(n-3.0*floor(n/3.0)-1.0)*0.94*dep;
 let b=(p-vec2<f32>(x,-0.11-dep))/(dep*0.55);
 let body=min(sd_box(b,vec2<f32>(0.40,0.13)),sd_box(b-vec2<f32>(0.0,0.14),vec2<f32>(0.29,0.11)));
 let rear=sd_box(vec2<f32>(abs(b.x)-0.285,b.y+0.035),vec2<f32>(0.080,0.030));
 let mask=traffic*smoothstep(0.0,0.1,f)*(1.0-smoothstep(0.92,1.0,f));
 let paint=mix(c2,c5,fract(n*0.618))*0.78;
 let glass=sd_box(b-vec2<f32>(0.0,0.158),vec2<f32>(0.23,0.056));
 col=mix(col,mix(paint,c1,1.0-smoothstep(0.0,0.025,glass)),mask*(1.0-smoothstep(0.0,0.025,body)));
 col=mix(col,c3,mask*halo(rear,0.055));
}
return mix(bg,col,strength);
